1	//! How Qwen3 plugs into the engine contract — the whole adaptation, in one
2	//! file.
3	//!
4	//! [`Qwen3Scheduler`] implements [`pegainfer_frontend::engine::Scheduler`]:
5	//! the contract's driver polls `submit`/`step`/`metrics`; everything
6	//! south of here ([`crate::scheduler`], the executor) deals in the contract's
7	//! [`RequestId`] and pure effect data. This file owns the only two
8	//! contract-facing responsibilities:
9	//!
10	//! - the **ledger writes**: translating each step's effects into verdicts and
11	//!   tokens recorded on the [`RequestLedger`] by id;
12	//! - **engine assembly**: building the executor and returning the
13	//!   [`Engine`] bundle from `launch`.
14	//!
15	//! Cancellation is reactive: the frontend flips a request's abort flag and
16	//! this adapter retires it, at the top of the next step while it is queued or
17	//! waiting for its next prefill chunk, and on its next touch once it is
18	//! decoding or has a prefill in flight — the scheduler mechanics never see
19	//! aborts. Finishes ride the committed step unless the executor withholds
20	//! them ([`ModelExecutor::withholds_finishes`]): a P/D prefill executor takes
21	//! them as [`RequestLedger::defer_finish`] tokens and delivers each request's
22	//! final record once its KV saves are peer-visible.
23	
24	#[cfg(test)]
25	mod tests;
26	
27	use std::collections::VecDeque;
28	use std::path::Path;
29	
30	use anyhow::Result;
31	use log::info;
32	use log::warn;
33	use pegainfer_frontend::engine::DeferredFinish;
34	use pegainfer_frontend::engine::Engine;
35	use pegainfer_frontend::engine::EngineInfo;
36	use pegainfer_frontend::engine::FinishReason;
37	use pegainfer_frontend::engine::KvCapacity;
38	use pegainfer_frontend::engine::LoraClient;
39	use pegainfer_frontend::engine::LoraControl;
40	use pegainfer_frontend::engine::LoraControlReceiver;
41	use pegainfer_frontend::engine::PromptEcho;
42	use pegainfer_frontend::engine::QueuedRequest;
43	use pegainfer_frontend::engine::RejectReason;
44	use pegainfer_frontend::engine::RequestLedger;
45	use pegainfer_frontend::engine::Scheduler;
46	use pegainfer_frontend::engine::SchedulerMetrics;
47	use pegainfer_frontend::engine::StopCause;
48	use pegainfer_frontend::engine::spawn_scheduler;
49	use pegainfer_kernels::ops::NumericPolicy;
50	use pegainfer_kernels::ops::numeric_policy;
51	use rand::SeedableRng;
52	use rand::rngs::StdRng;
53	
54	use crate::Qwen3LoraOptions;
55	use crate::Qwen3OffloadOptions;
56	use crate::executor::ModelExecutor;
57	use crate::executor::Qwen3Executor;
58	use crate::executor::RequestId;
59	use crate::executor::WorkerLost;
60	use crate::scheduler::ActiveRequestState;
61	use crate::scheduler::PendingRequest;
62	use crate::scheduler::RejectReason as AdmissionReject;
63	use crate::scheduler::admit_deferred_requests;
64	use crate::scheduler::admitted_future_blocks;
65	use crate::scheduler::block_on_loading;
66	use crate::scheduler::effects::DecodeEffect;
67	use crate::scheduler::effects::PendingEffect;
68	use crate::scheduler::effects::StepEffects;
69	use crate::scheduler::failure_target_ids;
70	use crate::scheduler::max_request_tokens;
71	use crate::scheduler::offer_prefetch;
72	use crate::scheduler::phase_trace::PhaseTracker;
73	use crate::scheduler::plan::ExecutionArtifacts;
74	use crate::scheduler::plan::ExecutionPlan;
75	use crate::scheduler::plan::execute_plan;
76	use crate::scheduler::reclaim_ready_prefetch;
77	use crate::scheduler::reject_unknown_lora_requests;
78	use crate::scheduler::release_rejected;
79	use crate::scheduler::resolve::resolve_step;
80	use crate::scheduler::runtime_plan;
81	use crate::scheduler::servable_len;
82	use crate::scheduler::take_prefill_chunks;
83	use crate::speculative::DraftModel;
84	use crate::weights::Qwen3MemoryOptions;
85	
86	// ── Engine assembly ─────────────────────────────────────────────────────
87	
88	#[allow(clippy::too_many_arguments)]
89	pub(crate) fn start_qwen3(
90	    model_path: &str,
91	    enable_cuda_graph: bool,
92	    device_ordinals: &[usize],
93	    seed: u64,
94	    offload_options: Qwen3OffloadOptions,
95	    no_prefix_cache: bool,
96	    max_prefill_tokens: usize,
97	    memory_options: Qwen3MemoryOptions,
98	    decode_overlap: crate::DecodeOverlap,
99	    draft: Option<DraftModel<'_>>,
100	    dump_graph_png: Option<&Path>,
101	) -> Result<Engine> {
102	    let mut executor = Qwen3Executor::from_runtime_with_decode_environment(
103	        model_path,
104	        enable_cuda_graph,
105	        device_ordinals,
106	        Qwen3LoraOptions::default(),
107	        offload_options,
108	        max_prefill_tokens,
109	        draft,
110	        memory_options,
111	        decode_overlap,
112	    )?;
113	    if let Some(path) = dump_graph_png {
114	        let summary = executor.dump_decode_graph_png(path)?;
115	        info!(
116	            "Qwen3 decode CUDA Graph exported: nodes={}, kernels={}, edges={}, dot={}, png={}",
117	            summary.nodes,
118	            summary.kernels,
119	            summary.edges,
120	            summary.dot_path.display(),
121	            summary.png_path.display()
122	        );
123	    }
124	    executor.set_no_prefix_cache(no_prefix_cache);
125	    executor.enable_decode_overlap(decode_overlap)?;
126	    // Speculative decoding loads its draft model after the target is up (the
127	    // draft is built against the target's embeddings/head) and forces the
128	    // prefix cache off, so it must follow set_no_prefix_cache. Its GPU footprint
129	    // was already reserved during profiling from the draft path passed above.
130	    if let Some(draft) = draft {
131	        executor.load_draft_model(draft)?;
132	    }
133	
134	    Ok(start_with_executor(
135	        executor,
136	        seed,
137	        max_prefill_tokens,
138	        false,
139	    ))
140	}

