380	    /// Absorb a step execution error by failing the batch it touched. A lost
381	    /// rank worker leaves nothing to serve with, so that error is returned and
382	    /// the driver winds the engine down.
383	    fn absorb_step_failure(
384	        &mut self,
385	        targets: Vec<RequestId>,
386	        error: anyhow::Error,
387	        ledger: &mut RequestLedger,
388	    ) -> Result<()> {
389	        if WorkerLost::caused(&error) {
390	            return Err(error);
391	        }
392	        warn!("Execution step failed: {error}");
393	        self.fail_touched_requests(targets, &error.to_string(), ledger);
394	        Ok(())
395	    }
