397	    /// Translate one step's pure effects into ledger writes, executor
398	    /// bookkeeping, and state transitions. The old per-token send-failure
399	    /// signal is replaced by explicit abort probes on the ledger.
400	    fn apply_effects(&mut self, effects: StepEffects, ledger: &mut RequestLedger) {
401	        // Finishes are collected and resolved at the end of the step. A
402	        // withholding executor (P/D prefill: `Finished` may leave only once
403	        // this step's KV saves are peer-visible) takes them as
404	        // [`DeferredFinish`] tokens and delivers off the scheduler thread —
405	        // each carries the request's whole buffered record, so late delivery
406	        // cannot reorder. Everyone else finishes through the ledger, so the
407	        // terminal rides the committed step, which the driver ships after
408	        // publishing metrics — the finishing batch's send-time stats then
409	        // read the drained occupancy instead of racing the publish.
410	        // Fold this step's prefix-cache counters into the cumulative totals
411	        // before any effect is dropped, so retries/re-queues never lose a count.
412	        self.prefix_cache_queries += effects.prefix_queries;
413	        self.prefix_cache_hits += effects.prefix_hits;
414	
415	        let mut finishes: Vec<(RequestId, FinishReason, Option<StopCause>)> = Vec::new();
416	
417	        for cached in effects.cached {
418	            if ledger.is_active(cached.request_id) {
419	                ledger.set_cached_tokens(cached.request_id, cached.cached_tokens);
420	            }
421	        }
422	
423	        for echo in effects.prompt_echoes {
424	            if ledger.is_active(echo.request_id) {
425	                ledger.echo_prompt(
426	                    echo.request_id,
427	                    PromptEcho {
428	                        ids: echo.ids,
429	                        logprobs: echo.logprobs,
430	                    },
431	                );
432	            }
433	        }
434	
435	        let mut to_retire = Vec::new();
436	        for effect in effects.decode {
437	            match effect {
438	                DecodeEffect::Finish {
439	                    request_id,
440	                    token,
441	                    logprob,
442	                    finish_reason,
443	                    stop_cause,
444	                } => {
445	                    let Some(index) = self
446	                        .active
447	                        .iter()
448	                        .position(|req| req.request_id == request_id)
449	                    else {
450	                        continue;
451	                    };
452	                    if ledger.is_active(request_id) {
453	                        if ledger.is_aborted(request_id) {
454	                            ledger.retire(request_id);
455	                        } else {
456	                            ledger.push_tokens(request_id, &[token], &[logprob]);
457	                            finishes.push((request_id, finish_reason, stop_cause));
458	                        }
459	                    }
460	                    self.tracker.finish(request_id);
461	                    let _ = self.executor.drop_request(request_id);
462	                    to_retire.push(index);
463	                }
464	                DecodeEffect::Continue {
465	                    request_id,
466	                    token,
467	                    logprob,
468	                    completion_tokens,
469	                } => {
470	                    let Some(index) = self
471	                        .active
472	                        .iter()
473	                        .position(|req| req.request_id == request_id)
474	                    else {
475	                        continue;
476	                    };
477	                    if ledger.is_aborted(request_id) {
478	                        self.retire_aborted(request_id, ledger);
479	                        to_retire.push(index);
480	                    } else {
481	                        ledger.push_tokens(request_id, &[token], &[logprob]);
482	                        let req = &mut self.active[index];
483	                        req.last_token = token;
484	                        req.generated_count = completion_tokens;
485	                    }
486	                }
487	                DecodeEffect::ContinueMany {
488	                    request_id,
489	                    tokens,
490	                    completion_tokens,
491	                } => {
492	                    let Some(index) = self
493	                        .active
494	                        .iter()
495	                        .position(|req| req.request_id == request_id)
496	                    else {
497	                        continue;
498	                    };
499	                    if ledger.is_aborted(request_id) {
500	                        self.retire_aborted(request_id, ledger);
501	                        to_retire.push(index);
502	                    } else {
503	                        ledger.push_tokens(request_id, &tokens, &[]);
504	                        if let Some(&last) = tokens.last() {
505	                            let req = &mut self.active[index];
506	                            req.last_token = last;
507	                            req.generated_count = completion_tokens;
508	                        }
509	                    }
510	                }
511	                DecodeEffect::FinishMany {
512	                    request_id,
513	                    tokens,
514	                    finish_reason,
515	                    stop_cause,
516	                } => {
517	                    let Some(index) = self
518	                        .active
519	                        .iter()
520	                        .position(|req| req.request_id == request_id)
521	                    else {
522	                        continue;
523	                    };
524	                    if ledger.is_active(request_id) {
525	                        if ledger.is_aborted(request_id) {
526	                            ledger.retire(request_id);
527	                        } else {
528	                            ledger.push_tokens(request_id, &tokens, &[]);
529	                            finishes.push((request_id, finish_reason, stop_cause));
530	                        }
531	                    }
532	                    self.tracker.finish(request_id);
533	                    let _ = self.executor.drop_request(request_id);
534	                    to_retire.push(index);
535	                }
536	            }
537	        }
538	        to_retire.sort_unstable();
539	        to_retire.dedup();
540	        for &i in to_retire.iter().rev() {
541	            self.active.swap_remove(i);
542	        }
543	
544	        // Requests that ran a non-final chunk this step came off the front of
545	        // the prefilling queue; splicing them back at the front (in step
546	        // order, which is request-id order) keeps the queue FIFO so chunked
547	        // prompts finish before newer arrivals start.
548	        let mut continued: Vec<PendingRequest> = Vec::new();
549	        for effect in effects.pending {
550	            match effect {
551	                PendingEffect::ContinuePrefill { req } => {
552	                    if ledger.is_aborted(req.request_id) {
553	                        let request_id = req.request_id;
554	                        self.retire_aborted(request_id, ledger);
555	                    } else {
556	                        continued.push(req);
557	                    }
558	                }
559	                PendingEffect::EmitAndFinish {
560	                    request_id,
561	                    token,
562	                    logprob,
563	                    finish_reason,
564	                    stop_cause,
565	                } => {
566	                    if ledger.is_active(request_id) {
567	                        if ledger.is_aborted(request_id) {
568	                            ledger.retire(request_id);
569	                        } else {
570	                            ledger.push_tokens(request_id, &[token], &[logprob]);
571	                            finishes.push((request_id, finish_reason, stop_cause));
572	                        }
573	                    }
574	                    self.tracker.finish(request_id);
575	                    let _ = self.executor.drop_request(request_id);
576	                }
577	                PendingEffect::Promote {
578	                    state,
579	                    first_token,
580	                    logprob,
581	                } => {
582	                    let request_id = state.request_id;
583	                    if ledger.is_aborted(request_id) {
584	                        self.retire_aborted(request_id, ledger);
585	                    } else {
586	                        ledger.push_tokens(request_id, &[first_token], &[logprob]);
587	                        self.tracker.enter_decode(request_id);
588	                        self.active.push(state);
589	                    }
590	                }
591	            }
592	        }
593	        self.prefilling.splice(0..0, continued);
594	
595	        if !finishes.is_empty() {
596	            if self.executor.withholds_finishes() {
597	                let withheld: Vec<DeferredFinish> = finishes
598	                    .into_iter()
599	                    .map(|(request_id, reason, stop_cause)| {
600	                        ledger.defer_finish_with_cause(request_id, reason, stop_cause)
601	                    })
602	                    .collect();
603	                self.executor.release_finished_events(withheld);
604	            } else {
605	                for (request_id, reason, stop_cause) in finishes {
606	                    ledger.finish_with_cause(request_id, reason, stop_cause);
607	                }
608	            }
609	        }
610	    }
