619	impl<E: ModelExecutor> Scheduler for Qwen3Scheduler<E> {
620	    fn submit(&mut self, request: QueuedRequest) {
621	        // Already-aborted requests ride the normal path: admission re-checks
622	        // the abort flag and retires them (`admit_or_retire`).
623	        let QueuedRequest { id, request } = request;
624	        self.tracker.enter_queue(id, request.trace_parent);
625	        let pending = PendingRequest::from_request(id, request);
626	        if self.pending_control.is_empty() {
627	            self.deferred.push(pending);
628	        } else {
629	            self.post_control_deferred.push(pending);
630	        }
631	    }
632	
633	    fn step(&mut self, ledger: &mut RequestLedger) -> Result<()> {
634	        // 0. Pull queued LoRA commands off the engine's private channel; they
635	        // apply only once the scheduler drains idle (`drain_idle_control`).
636	        if let Some(lora_rx) = &self.lora_rx {
637	            while let Ok(control) = lora_rx.try_recv() {
638	                self.pending_control.push_back(control);
639	            }
640	        }
641	
642	        // 1. Poll in-flight async prefill (decode-overlap mode).
643	        if self.inflight_prefill_pending.is_some()
644	            && let Some(prefill_result) = self.executor.poll_async_prefill()
645	        {
646	            let pending = self
647	                .inflight_prefill_pending
648	                .take()
649	                .expect("checked in-flight prefill above");
650	            info!(
651	                "decode-overlap: async prefill completed ({} reqs)",
652	                pending.len()
653	            );
654	            let artifacts = ExecutionArtifacts::Prefill {
655	                pending,
656	                result: prefill_result,
657	            };
658	            let effects = resolve_step(&self.executor, &self.active, artifacts);
659	            self.apply_effects(effects, ledger);
660	        }
661	        self.retire_aborted_waiting(ledger);
662	
663	        // 2. Reclaim settled prefetches, then offer fresh requests to
664	        // prefetch. Control commands gate generation, so only offer once no
665	        // control is pending (a prefetch must not race ahead of an adapter
666	        // load it depends on).
667	        let reserve_floor = admitted_future_blocks(
668	            &self.executor,
669	            &self.active,
670	            &self.prefilling,
671	            self.inflight_prefills(),
672	        );
673	        reclaim_ready_prefetch(
674	            &mut self.executor,
675	            &mut self.deferred,
676	            &mut self.loading,
677	            reserve_floor,
678	        );
679	        if self.pending_control.is_empty() {
680	            offer_prefetch(
681	                &mut self.executor,
682	                &mut self.deferred,
683	                &mut self.loading,
684	                reserve_floor,
685	            );
686	        }
687	
688	        // 3. Once idle, apply pending control commands before admitting newer
689	        // generation requests that arrived behind them.
690	        if self.idle() {
691	            self.drain_idle_control();
692	            if self.pending_control.is_empty() && !self.post_control_deferred.is_empty() {
693	                self.deferred.append(&mut self.post_control_deferred);
694	            }
695	        }
696	
697	        // 4. Still nothing runnable → wait on an in-flight prefetch DMA (its
698	        // request prefills next), else hand control back to the polling
699	        // driver.
700	        if self.idle() {
701	            if !self.loading.is_empty() {
702	                let reserve_floor = admitted_future_blocks(
703	                    &self.executor,
704	                    &self.active,
705	                    &self.prefilling,
706	                    self.inflight_prefills(),
707	                );
708	                block_on_loading(
709	                    &mut self.executor,
710	                    &mut self.deferred,
711	                    &mut self.loading,
712	                    reserve_floor,
713	                );
714	            }
715	            return Ok(());
716	        }
717	
718	        // 5. Validate + admit; every verdict closes the request's queued
719	        //    ledger account.
720	        let lora_validation =
721	            reject_unknown_lora_requests(std::mem::take(&mut self.deferred), &self.executor);
722	        for rejected in &lora_validation.rejected {
723	            let reason = RejectReason::UnknownLoraAdapter {
724	                name: rejected
725	                    .lora_adapter
726	                    .clone()
727	                    .expect("only requests naming an adapter can fail LoRA validation"),
728	            };
729	            self.reject_pending(rejected, reason, ledger);
730	        }
731	        let admission = admit_deferred_requests(
732	            lora_validation.accepted,
733	            &self.active,
734	            &self.prefilling,
735	            self.inflight_prefills(),
736	            self.executor.block_size(),
737	            self.executor.available_blocks(),
738	            self.executor.max_request_blocks(),
739	            self.executor.max_context_tokens(),
740	            self.executor.max_decode_batch_size(),
741	            self.max_prefill_tokens,
742	            |id| self.executor.prefetched_blocks(id),
743	        );
744	        for (rejected, reason) in &admission.rejected {
745	            self.reject_pending(rejected, contract_reject_reason(rejected, *reason), ledger);
746	        }
747	        self.deferred = admission.deferred;
748	        for req in admission.pending {
749	            if self.admit_or_retire(&req, ledger) {
750	                self.prefilling.push(req);
751	            }
752	        }
753	
754	        // 6. Chunk selection. While an async prefill is in flight, only
755	        // decode runs.
756	        let pending = if self.inflight_prefill_pending.is_some() {
757	            Vec::new()
758	        } else {
759	            take_prefill_chunks(
760	                &mut self.prefilling,
761	                self.max_prefill_tokens,
762	                matches!(
763	                    numeric_policy(),
764	                    NumericPolicy::Pin | NumericPolicy::PerToken
765	                ),
766	            )
767	        };
768	        // These requests' prompt work is about to hit the GPU this step:
769	        // close their queue span, open prefill. Idempotent, so chunked
770	        // prefill across steps opens the prefill span once (on the first
771	        // chunk).
772	        for req in &pending {
773	            self.tracker.enter_prefill(req.request_id);
774	        }
775	
776	        let Some(plan) = runtime_plan(&self.executor, &self.active, pending) else {
777	            return Ok(());
778	        };
779	
780	        // 7. Decode-overlap path: when a Unified plan appears and overlap
781	        // streams are active (and no async prefill is already in-flight),
782	        // execute_unified internally uses SplitConcurrent which only syncs
783	        // decode and defers the prefill sync. The prefill result is polled at
784	        // the top of a later step.
785	        if self.executor.has_decode_overlap()
786	            && self.inflight_prefill_pending.is_none()
787	            && let ExecutionPlan::Unified { pending } = plan
788	        {
789	            let prefill_tokens: usize = pending.iter().map(|r| r.step_chunk).sum();
790	            info!(
791	                "decode-overlap: unified step with async prefill ({} reqs, ~{} tokens)",
792	                pending.len(),
793	                prefill_tokens
794	            );
795	            let pending_for_poll = pending.clone();
796	            let unified_plan = ExecutionPlan::Unified { pending };
797	            let targets = failure_target_ids(&self.active, &unified_plan);
798	            let artifacts = match execute_plan(
799	                &mut self.executor,
800	                &mut self.active,
801	                unified_plan,
802	                &mut self.rng,
803	            ) {
804	                Ok(v) => v,
805	                Err(e) => return self.absorb_step_failure(targets, e, ledger),
806	            };
807	            // Only decode effects come out of the unified result (its prefill
808	            // request list is empty until the poll resolves).
809	            let effects = resolve_step(&self.executor, &self.active, artifacts);
810	            self.apply_effects(effects, ledger);
811	            self.inflight_prefill_pending = Some(pending_for_poll);
812	            return Ok(());
813	        }
814	
815	        // 8. Execute, resolve, apply. A step failure kills the touched batch
816	        // but not the engine, unless a rank worker is gone.
817	        let targets = failure_target_ids(&self.active, &plan);
818	        let artifacts =
819	            match execute_plan(&mut self.executor, &mut self.active, plan, &mut self.rng) {
820	                Ok(v) => v,
821	                Err(e) => return self.absorb_step_failure(targets, e, ledger),
822	            };
823	        let effects = resolve_step(&self.executor, &self.active, artifacts);
824	        self.apply_effects(effects, ledger);
825	        Ok(())
