1721	        if retained_before && !self.retains_completed_kv_blocks() {
1722	            self.kv_mgr.pool().evict_inactive();
1723	        }
1724	    }
1725	
1726	    /// Configure two-stream prefill/decode overlap (see [`crate::DecodeOverlap`]).
1727	    /// A no-op for [`crate::DecodeOverlap::Off`]; otherwise sets up the streams,
1728	    /// returning an error if the GPU/driver cannot honor the requested mode.
1729	    pub(crate) fn enable_decode_overlap(&mut self, overlap: crate::DecodeOverlap) -> Result<()> {
1730	        // Pre-capture backstop: a runtime caller could set Pin then enable overlap here, bypassing the
1731	        // engine-entry guard. launch_gemm_pin also bails on the resulting stream override, but only mid
1732	        // graph-capture/replay (a hot-path failure) — rejecting here moves it to a safe point.
1733	        anyhow::ensure!(
1734	            pegainfer_kernels::ops::numeric_policy() != pegainfer_kernels::ops::NumericPolicy::Pin
1735	                || matches!(overlap, crate::DecodeOverlap::Off),
1736	            "--batch-invariant (NumericPolicy::Pin) is not compatible with decode-overlap: the stream override would force the pinned GEMM to bail at runtime"
