/// Flush pending offload saves into the host read cache so a following
/// query can see them. A persistence barrier for handoff and tests; no-op
/// without offload.
pub fn flush_offload_saves(&self) {
    if let Some(offload) = &self.offload {
        offload.flush_saves();
    }
}

